//! 🧾️ Public Source header/failure/input disposition laws use the shared neutral corpus.
use semio_framework_actor_receipt::*;
use semio_framework_actor::RetainedTurnInput;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
mod tests{use super::*;use semio_framework_actor::{ActorFailureCallReference,ActorFailureCallKind,ActorFailureOutcome,ActorFailureCallFailure};fn input(epoch:u64)->RetainedTurnInput{RetainedTurnInput{operation:1,generation:1,epoch,work:semio_framework_actor::OriginalActorTurnWork{clock_binding:9,absolute_deadline_us:1000,fuel:10000},grant:RetainedCloneGrant{maximum_items:128,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:64}}}#[test]fn actor_failure_frame_is_distinct_and_qualifies_exact_current_signal_or_prior_cause(){let reference=ActorFailureCallReference{failed_epoch:7,call_kind:ActorFailureCallKind::Poll};let escrow=OriginalEscrowExtent{pointer:3000,length:48};let mut receipt=ActorFailureFixedReceipt::empty();let signal=ActorFailureCall{input:input(7),spent:Default::default(),work_units_spent:0,reference,status:ActorFailureStatus::Signal,refusal:Some(ActorFailureCallFailure::Semantic)};receipt.write(signal,escrow).unwrap();assert_eq!(&receipt.bytes()[..4],b"SAF1");assert_eq!(ActorFailureFixedReceipt::read(receipt.bytes()).unwrap(),(signal,escrow));assert!(OriginalOwnedJobFixedReceipt::read(receipt.bytes()).is_err());validate_original_source_header_body(receipt.bytes()).unwrap();let publish=ActorFailureCall{input:input(8),status:ActorFailureStatus::Publish{outcome:Some(ActorFailureOutcome{reference,byte_length:17})},refusal:None,..signal};receipt.write(publish,escrow).unwrap();assert_eq!(ActorFailureFixedReceipt::read(receipt.bytes()).unwrap(),(publish,escrow));let mut bad=*receipt.bytes();bad[160..168].copy_from_slice(&24u64.to_le_bytes());assert_ne!(ActorFailureFixedReceipt::read(&bad).unwrap().0.reference,reference);bad[152..160].copy_from_slice(&8u64.to_le_bytes());assert!(ActorFailureFixedReceipt::read(&bad).is_err());}#[test]fn actor_failure_reader_matches_the_shared_independent_case_oracle(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let mut bytes=[0u8;184];bytes[..4].copy_from_slice(b"SAF1");for(i,key)in["kind","flags","refusal"].into_iter().enumerate(){bytes[4+i]=row[key].as_u64().unwrap()as u8;}let call=OriginalActorFixedCall{input:input(row["callerEpoch"].as_u64().unwrap()),spent:Default::default(),work_units_spent:0,kind:OriginalActorFixedKind::Failure{authority:None}};let mut writer=OriginalSliceHeaderWriter::new(&mut bytes[8..152],144).unwrap();OriginalActorFixedReceipt::write_to(&mut writer,call,OriginalEscrowExtent{pointer:3000,length:48}).unwrap();for(i,key)in["epoch","callKind","a","b"].into_iter().enumerate(){bytes[152+8*i..160+8*i].copy_from_slice(&row[key].as_u64().unwrap().to_le_bytes());}assert_eq!(ActorFailureFixedReceipt::read(&bytes).is_ok(),row["valid"].as_bool().unwrap());}}#[test]fn actor_failure_and_quiescent_prefix_shapes_reject_unissued_flags(){let input=input(8);let escrow=OriginalEscrowExtent{pointer:3000,length:48};let mut receipt=OriginalActorFixedReceipt::empty();receipt.write(OriginalActorFixedCall{input,spent:Default::default(),work_units_spent:0,kind:OriginalActorFixedKind::QuiescentForCoreRetirement},escrow).unwrap();validate_original_source_header_body(receipt.bytes()).unwrap();let mut bad=*receipt.bytes();bad[5]=1;assert!(validate_original_source_header_prefix(&bad).is_err());let mut bytes=[0;152];let mut sink=OriginalSliceHeaderWriter::new(&mut bytes,152).unwrap();OriginalActorFixedReceipt::write_failure_to(&mut sink,OriginalActorFixedCall{input,spent:Default::default(),work_units_spent:0,kind:OriginalActorFixedKind::Failure{authority:None}},escrow,152).unwrap();validate_original_source_header_body(&bytes).unwrap();bytes[151]=1;assert!(validate_original_source_header_body(&bytes).is_err());}}
mod input_failure_tests{use super::*;#[test]fn input_failure_matches_the_shared_wire_return_proof_cases(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🔣️.json")).unwrap();for row in corpus["inputFailures"].as_array().unwrap(){let mut bytes=[0u8;152];bytes[..4].copy_from_slice(b"SAC3");bytes[4]=row["kind"].as_u64().unwrap()as u8;bytes[5]=row["flags"].as_u64().unwrap()as u8;bytes[6]=row["refusal"].as_u64().unwrap()as u8;let parsed=OriginalActorFixedReceipt::read(&bytes[..row["length"].as_u64().unwrap()as usize]);assert_eq!(parsed.is_ok(),row["valid"].as_bool().unwrap());if let Ok((call,_))=parsed{assert_eq!(call.kind,OriginalActorFixedKind::InputFailure{input_returned:bytes[5]==2});assert_eq!(call.kind.input_disposition(),Some((false,bytes[5]==2,true)));assert!(call.kind.is_failure_for(semio_framework_actor::ActorFailureCallKind::AdmitActorInput));assert!(!call.kind.is_failure_for(semio_framework_actor::ActorFailureCallKind::Poll));let mut out=[0u8;144];OriginalActorFixedReceipt::write_into(&mut out,call,OriginalEscrowExtent{pointer:0,length:0}).unwrap();assert_eq!(&out[..8],&bytes[..8]);}}}}